import numpy as np

def naive_random_init(input_size, output_size, scale=1.0):
    return np.random.RandomState(42).normal(scale=scale, size=(input_size, output_size))

def forward_pass(x, weights):
    return x @ weights

sample_input = np.random.RandomState(0).normal(size=(1, 100))

for input_size in [10, 100, 1000]:
    weights = naive_random_init(input_size, 50)
    test_input = np.random.RandomState(0).normal(size=(1, input_size))
    output = forward_pass(test_input, weights)
    print(f"Input size {input_size:5d}: output std deviation = {output.std():.4f}")

print("\nNotice the output's scale grows considerably as input size grows,")
print("exactly the scale problem covered in this topic, since naive initialization ignores layer size entirely")
